use crate::config::Config;
use crate::ha_client::{EntityState, HomeAssistantClient};
use anyhow::Result;
use crossterm::event::{self, KeyCode};
use ratatui::{
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, List, ListItem, ListState, Paragraph, Clear},
    Frame,
};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::Instant;

const CYAN: Color = Color::Rgb(0, 255, 255);
const MAGENTA: Color = Color::Rgb(255, 0, 255);
const NEON_GREEN: Color = Color::Rgb(0, 255, 100);
const ELECTRIC_BLUE: Color = Color::Rgb(100, 200, 255);
const ORANGE: Color = Color::Rgb(255, 165, 0);
const HOT_PINK: Color = Color::Rgb(255, 100, 150);
const DARK_BG: Color = Color::Rgb(10, 10, 20);
const MUTED: Color = Color::Rgb(80, 80, 100);
const BRIGHT_WHITE: Color = Color::Rgb(240, 240, 255);
const GRID_COLOR: Color = Color::Rgb(30, 30, 50);

#[derive(Debug, Clone, PartialEq)]
pub enum AppMode {
    Normal,
    Search,
    EntityDetail,
    Help,
    Error,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum DomainFilter {
    All,
    Lights,
    Switches,
    Climate,
    Sensors,
    Media,
    Automations,
    BinarySensors,
}

impl DomainFilter {
    fn all() -> Vec<Self> {
        vec![
            Self::All,
            Self::Lights,
            Self::Switches,
            Self::Climate,
            Self::Sensors,
            Self::Media,
            Self::Automations,
            Self::BinarySensors,
        ]
    }

    fn icon(&self) -> &'static str {
        match self {
            Self::All => "◈",
            Self::Lights => "◉",
            Self::Switches => "⏻",
            Self::Climate => "◈",
            Self::Sensors => "◎",
            Self::Media => "▶",
            Self::Automations => "⚡",
            Self::BinarySensors => "●",
        }
    }

    fn title(&self) -> &'static str {
        match self {
            Self::All => "ALL",
            Self::Lights => "LIGHTS",
            Self::Switches => "SWITCHES",
            Self::Climate => "CLIMATE",
            Self::Sensors => "SENSORS",
            Self::Media => "MEDIA",
            Self::Automations => "AUTO",
            Self::BinarySensors => "BINARY",
        }
    }

    fn matches_domain(&self, entity_id: &str) -> bool {
        let domain = entity_id.split('.').next().unwrap_or("");
        match self {
            Self::All => true,
            Self::Lights => domain == "light",
            Self::Switches => domain == "switch" || domain == "input_boolean",
            Self::Climate => domain == "climate",
            Self::Sensors => domain == "sensor",
            Self::Media => domain == "media_player",
            Self::Automations => domain == "automation" || domain == "script",
            Self::BinarySensors => domain == "binary_sensor",
        }
    }
}

pub struct App {
    #[allow(dead_code)]
    pub config: Option<Config>,
    pub ha_client: Option<Arc<HomeAssistantClient>>,
    pub entities: Vec<EntityState>,
    pub filtered_entities: Vec<EntityState>,
    pub list_state: ListState,
    pub mode: AppMode,
    pub search_query: String,
    pub domain_filter: DomainFilter,
    pub domain_filter_index: usize,
    pub error_message: Option<String>,
    pub last_update: Option<Instant>,
    pub loading: bool,
    pub selected_entity: Option<EntityState>,
    pub should_quit: bool,
    #[allow(dead_code)]
    pub scroll_offset: u16,
    pub demo_mode: bool,
    pub tick: u64,
}

impl App {
    pub async fn new(config: Config) -> Result<Self> {
        let ha_client = HomeAssistantClient::new(
            config.homeassistant.url.clone(),
            config.homeassistant.token.clone(),
        );
        Ok(Self {
            config: Some(config),
            ha_client: Some(Arc::new(ha_client)),
            entities: Vec::new(),
            filtered_entities: Vec::new(),
            list_state: ListState::default(),
            mode: AppMode::Normal,
            search_query: String::new(),
            domain_filter: DomainFilter::All,
            domain_filter_index: 0,
            error_message: None,
            last_update: None,
            loading: true,
            selected_entity: None,
            should_quit: false,
            scroll_offset: 0,
            demo_mode: false,
            tick: 0,
        })
    }

    pub fn new_demo() -> Self {
        Self {
            config: None,
            ha_client: None,
            entities: Vec::new(),
            filtered_entities: Vec::new(),
            list_state: ListState::default(),
            mode: AppMode::Normal,
            search_query: String::new(),
            domain_filter: DomainFilter::All,
            domain_filter_index: 0,
            error_message: None,
            last_update: None,
            loading: true,
            selected_entity: None,
            should_quit: false,
            scroll_offset: 0,
            demo_mode: true,
            tick: 0,
        }
    }

    pub fn tick(&mut self) {
        self.tick = self.tick.wrapping_add(1);
    }

    pub async fn load_entities(&mut self) {
        self.loading = true;
        self.error_message = None;

        if self.demo_mode {
            self.entities = create_demo_entities();
            self.apply_filter();
            self.last_update = Some(Instant::now());
            self.loading = false;
            return;
        }

        if let Some(client) = &self.ha_client {
            match client.get_states().await {
                Ok(entities) => {
                    self.entities = entities;
                    self.apply_filter();
                    self.last_update = Some(Instant::now());
                }
                Err(e) => {
                    self.error_message = Some(format!("Failed to load entities: {}", e));
                    self.mode = AppMode::Error;
                }
            }
        }

        self.loading = false;
    }

    pub fn apply_filter(&mut self) {
        let query = self.search_query.to_lowercase();
        self.filtered_entities = self
            .entities
            .iter()
            .filter(|e| {
                let matches_domain = self.domain_filter.matches_domain(&e.entity_id);
                let matches_search = if query.is_empty() {
                    true
                } else {
                    let name = e
                        .attributes
                        .get("friendly_name")
                        .and_then(|v| v.as_str())
                        .unwrap_or(&e.entity_id)
                        .to_lowercase();
                    name.contains(&query) || e.entity_id.to_lowercase().contains(&query)
                };
                matches_domain && matches_search
            })
            .cloned()
            .collect();

        if self.filtered_entities.is_empty() {
            self.list_state.select(None);
        } else {
            let current = self.list_state.selected().unwrap_or(0);
            self.list_state.select(Some(current.min(self.filtered_entities.len() - 1)));
        }
    }

    pub async fn handle_key_event(&mut self, key: event::KeyEvent) {
        match self.mode {
            AppMode::Normal => self.handle_normal_mode(key).await,
            AppMode::Search => self.handle_search_mode(key),
            AppMode::EntityDetail => self.handle_detail_mode(key),
            AppMode::Help => self.handle_help_mode(key),
            AppMode::Error => self.handle_error_mode(key),
        }
    }

    async fn handle_normal_mode(&mut self, key: event::KeyEvent) {
        match key.code {
            KeyCode::Char('q') => {
                self.should_quit = true;
            }
            KeyCode::Char('/') => {
                self.mode = AppMode::Search;
                self.search_query.clear();
            }
            KeyCode::Char('?') => {
                self.mode = AppMode::Help;
            }
            KeyCode::Char('r') => {
                self.load_entities().await;
            }
            KeyCode::Tab | KeyCode::Right => {
                self.cycle_domain_filter(1);
            }
            KeyCode::BackTab | KeyCode::Left => {
                self.cycle_domain_filter(-1);
            }
            KeyCode::Up | KeyCode::Char('k') => {
                self.list_state.select(self.list_state.selected().map(|s| {
                    if s > 0 {
                        s - 1
                    } else {
                        self.filtered_entities.len().saturating_sub(1)
                    }
                }));
            }
            KeyCode::Down | KeyCode::Char('j') => {
                self.list_state.select(self.list_state.selected().map(|s| {
                    if s < self.filtered_entities.len().saturating_sub(1) {
                        s + 1
                    } else {
                        0
                    }
                }));
            }
            KeyCode::Enter => {
                if let Some(selected) = self.list_state.selected() {
                    if let Some(entity) = self.filtered_entities.get(selected).cloned() {
                        self.selected_entity = Some(entity);
                        self.mode = AppMode::EntityDetail;
                    }
                }
            }
            KeyCode::Char(' ') => {
                self.toggle_selected_entity().await;
            }
            _ => {}
        }
    }

    fn handle_search_mode(&mut self, key: event::KeyEvent) {
        match key.code {
            KeyCode::Esc => {
                self.mode = AppMode::Normal;
                self.search_query.clear();
                self.apply_filter();
            }
            KeyCode::Enter => {
                self.mode = AppMode::Normal;
            }
            KeyCode::Backspace => {
                self.search_query.pop();
                self.apply_filter();
            }
            KeyCode::Char(c) => {
                self.search_query.push(c);
                self.apply_filter();
            }
            _ => {}
        }
    }

    fn handle_detail_mode(&mut self, key: event::KeyEvent) {
        match key.code {
            KeyCode::Esc | KeyCode::Enter => {
                self.mode = AppMode::Normal;
                self.selected_entity = None;
            }
            _ => {}
        }
    }

    fn handle_help_mode(&mut self, key: event::KeyEvent) {
        match key.code {
            KeyCode::Esc | KeyCode::Enter | KeyCode::Char('?') | KeyCode::Char('q') => {
                self.mode = AppMode::Normal;
            }
            _ => {}
        }
    }

    fn handle_error_mode(&mut self, key: event::KeyEvent) {
        match key.code {
            KeyCode::Esc | KeyCode::Enter | KeyCode::Char('q') => {
                self.mode = AppMode::Normal;
                self.error_message = None;
            }
            _ => {}
        }
    }

    fn cycle_domain_filter(&mut self, direction: i32) {
        let filters = DomainFilter::all();
        let new_index = (self.domain_filter_index as i32 + direction)
            .rem_euclid(filters.len() as i32) as usize;
        self.domain_filter_index = new_index;
        self.domain_filter = filters[new_index].clone();
        self.apply_filter();
    }

    async fn toggle_selected_entity(&mut self) {
        if let Some(selected) = self.list_state.selected() {
            if let Some(entity) = self.filtered_entities.get(selected).cloned() {
                let entity_id = entity.entity_id.clone();
                let domain = entity_id.split('.').next().unwrap_or("");

                if self.demo_mode {
                    let new_state = if entity.state == "on" { "off" } else { "on" };
                    for e in &mut self.entities {
                        if e.entity_id == entity_id {
                            e.state = new_state.to_string();
                        }
                    }
                    self.apply_filter();
                    self.last_update = Some(Instant::now());
                    return;
                }

                if let Some(client) = &self.ha_client {
                    let result = match domain {
                        "light" | "switch" | "input_boolean" | "fan" | "humidifier" => {
                            client.toggle(&entity_id).await
                        }
                        "automation" | "script" => {
                            if entity.state == "on" {
                                client.turn_off(&entity_id).await
                            } else {
                                client.turn_on(&entity_id).await
                            }
                        }
                        _ => return,
                    };

                    if let Err(e) = result {
                        self.error_message = Some(format!("Failed to toggle {}: {}", entity_id, e));
                        self.mode = AppMode::Error;
                    } else {
                        self.load_entities().await;
                    }
                }
            }
        }
    }

    fn count_on(&self) -> usize {
        self.entities.iter().filter(|e| {
            e.state == "on" || e.state == "playing" || e.state == "home"
        }).count()
    }

    fn count_off(&self) -> usize {
        self.entities.iter().filter(|e| {
            e.state == "off" || e.state == "idle" || e.state == "away"
        }).count()
    }
}

pub fn render_app(frame: &mut Frame, app: &App) {
    frame.render_widget(
        Block::default()
            .style(Style::default().bg(DARK_BG)),
        frame.area(),
    );

    let layout = Layout::default()
        .direction(Direction::Vertical)
        .margin(0)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(2),
        ])
        .split(frame.area());

    render_top_bar(frame, app, layout[0]);
    render_header(frame, app, layout[1]);
    render_main_content(frame, app, layout[2]);
    render_command_bar(frame, app, layout[3]);

    match app.mode {
        AppMode::EntityDetail => render_entity_detail(frame, app),
        AppMode::Help => render_help(frame),
        AppMode::Error => render_error(frame, app),
        _ => {}
    }
}

fn render_top_bar(frame: &mut Frame, app: &App, area: Rect) {
    let time_str = chrono::Local::now().format("%H:%M:%S").to_string();
    let date_str = chrono::Local::now().format("%Y-%m-%d").to_string();

    let pulse = if app.tick % 20 < 10 { "●" } else { "○" };

    let mode_indicator = if app.demo_mode {
        Span::styled(" ◈ DEMO MODE ◈ ", Style::default().fg(ORANGE).add_modifier(Modifier::BOLD))
    } else {
        Span::styled(" ● CONNECTED ", Style::default().fg(NEON_GREEN).add_modifier(Modifier::BOLD))
    };

    let loading_indicator = if app.loading {
        let spinner_chars = ["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"];
        Span::styled(
            format!(" {} ", spinner_chars[app.tick as usize % spinner_chars.len()]),
            Style::default().fg(CYAN).add_modifier(Modifier::BOLD))
    } else {
        Span::raw("")
    };

    let line = Line::from(vec![
        Span::styled("┌", Style::default().fg(MUTED)),
        Span::styled(" HOME ASSISTANT ", Style::default().fg(MUTED)),
        mode_indicator,
        Span::styled(pulse, Style::default().fg(CYAN)),
        Span::styled(" ── ", Style::default().fg(MUTED)),
        loading_indicator,
        Span::styled("─".repeat(area.width as usize / 3), Style::default().fg(GRID_COLOR)),
        Span::styled(format!(" {} {} ", date_str, time_str), Style::default().fg(ELECTRIC_BLUE)),
        Span::styled("┐", Style::default().fg(MUTED)),
    ]);

    frame.render_widget(Paragraph::new(line), area);
}

fn render_header(frame: &mut Frame, app: &App, area: Rect) {
    let filters = DomainFilter::all();
    let mut spans = vec![
        Span::styled("│ ", Style::default().fg(MUTED)),
    ];

    for (i, f) in filters.iter().enumerate() {
        let is_selected = i == app.domain_filter_index;
        let (icon_color, text_color) = if is_selected {
            (CYAN, BRIGHT_WHITE)
        } else {
            (MUTED, MUTED)
        };

        let bg = if is_selected {
            Color::Rgb(30, 30, 60)
        } else {
            DARK_BG
        };

        spans.push(Span::styled(" ", Style::default()));
        spans.push(Span::styled(f.icon(), Style::default().fg(icon_color).bg(bg)));
        spans.push(Span::styled(
            format!(" {} ", f.title()),
            Style::default().fg(text_color).bg(bg).add_modifier(Modifier::BOLD),
        ));

        if i < filters.len() - 1 {
            spans.push(Span::styled("│", Style::default().fg(GRID_COLOR)));
        }
    }

    spans.push(Span::styled(" ─", Style::default().fg(GRID_COLOR)));
    spans.push(Span::styled(
        format!(" entities: {} ", app.filtered_entities.len()),
        Style::default().fg(MUTED),
    ));
    spans.push(Span::styled("│", Style::default().fg(MUTED)));

    let paragraph = Paragraph::new(Line::from(spans))
        .style(Style::default().bg(DARK_BG));

    frame.render_widget(paragraph, area);
}

fn render_main_content(frame: &mut Frame, app: &App, area: Rect) {
    let columns = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(20),
        ])
        .split(area);

    render_left_edge(frame, app, columns[0]);
    render_entity_list(frame, app, columns[1]);
    render_stats_panel(frame, app, columns[2]);
}

fn render_left_edge(frame: &mut Frame, app: &App, area: Rect) {
    let mut lines = Vec::new();

    for i in 0..area.height {
        let char = if app.list_state.selected() == Some(i as usize) && (i as usize) < app.filtered_entities.len() {
            "▶"
        } else if i == area.height - 1 {
            "│"
        } else {
            "│"
        };

        let color = if char == "▶" { CYAN } else { MUTED };
        lines.push(Line::from(Span::styled(char, Style::default().fg(color))));
    }

    frame.render_widget(Paragraph::new(lines), area);
}

fn render_entity_list(frame: &mut Frame, app: &App, area: Rect) {
    let padding = " ".repeat(area.width as usize);

    let items: Vec<ListItem> = app
        .filtered_entities
        .iter()
        .enumerate()
        .map(|(idx, entity)| {
            let name = entity
                .attributes
                .get("friendly_name")
                .and_then(|v| v.as_str())
                .unwrap_or(&entity.entity_id);

            let state = crate::ha_client::format_entity_state(entity);
            let domain = crate::ha_client::get_entity_domain(&entity.entity_id);

            let (icon, state_color, domain_color) = get_entity_visuals(entity, domain);

            let is_selected = app.list_state.selected() == Some(idx);
            let bg = if is_selected { Color::Rgb(25, 25, 50) } else { DARK_BG };

            let state_indicator = get_state_indicator(entity);

            let line = Line::from(vec![
                Span::styled(" ", Style::default().bg(bg)),
                Span::styled(state_indicator, Style::default().fg(state_color).bg(bg)),
                Span::styled(" ", Style::default().bg(bg)),
                Span::styled(icon, Style::default().fg(domain_color).bg(bg)),
                Span::styled(" ", Style::default().bg(bg)),
                Span::styled(
                    truncate_str(name, 28),
                    Style::default()
                        .fg(if is_selected { BRIGHT_WHITE } else { Color::White })
                        .bg(bg)
                        .add_modifier(Modifier::BOLD),
                ),
                Span::styled(
                    " ─ ",
                    Style::default().fg(GRID_COLOR).bg(bg),
                ),
                Span::styled(
                    truncate_str(&state, 20),
                    Style::default().fg(state_color).bg(bg),
                ),
                Span::styled(
                    &padding,
                    Style::default().bg(bg),
                ),
            ]);

            ListItem::new(line)
        })
        .collect();

    let list = List::new(items)
        .style(Style::default().bg(DARK_BG))
        .highlight_style(
            Style::default()
                .bg(Color::Rgb(25, 25, 50)),
        );

    frame.render_stateful_widget(list, area, &mut app.list_state.clone());
}

fn render_stats_panel(frame: &mut Frame, app: &App, area: Rect) {
    let total = app.entities.len();
    let on_count = app.count_on();
    let off_count = app.count_off();

    let on_pct = if total > 0 { (on_count * 100) / total } else { 0 };

    let mut lines = vec![
        Line::from(Span::styled("┌─ STATUS ─────┐", Style::default().fg(CYAN))),
        Line::from(""),
        Line::from(vec![
            Span::styled("  Entities: ", Style::default().fg(MUTED)),
            Span::styled(format!("{}", total), Style::default().fg(BRIGHT_WHITE)),
        ]),
        Line::from(""),
        Line::from(vec![
            Span::styled("  Active:   ", Style::default().fg(MUTED)),
            Span::styled(format!("{}", on_count), Style::default().fg(NEON_GREEN)),
        ]),
        Line::from(vec![
            Span::styled("  Inactive: ", Style::default().fg(MUTED)),
            Span::styled(format!("{}", off_count), Style::default().fg(Color::Gray)),
        ]),
        Line::from(""),
    ];

    if total > 0 {
        lines.push(Line::from(vec![
            Span::styled("  [", Style::default().fg(MUTED)),
            Span::styled("█".repeat(on_pct / 5), Style::default().fg(NEON_GREEN)),
            Span::styled("░".repeat(20 - on_pct / 5), Style::default().fg(GRID_COLOR)),
            Span::styled("]", Style::default().fg(MUTED)),
        ]));
        lines.push(Line::from(vec![
            Span::styled("   ", Style::default()),
            Span::styled(format!("{}%", on_pct), Style::default().fg(NEON_GREEN)),
        ]));
    }

    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled("├─ QUICK ──────┤", Style::default().fg(CYAN))));
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled("  [r] Refresh", Style::default().fg(MUTED))));
    lines.push(Line::from(Span::styled("  [/] Search", Style::default().fg(MUTED))));
    lines.push(Line::from(Span::styled("  [?] Help", Style::default().fg(MUTED))));
    lines.push(Line::from(Span::styled("  [q] Quit", Style::default().fg(MUTED))));
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled("└──────────────┘", Style::default().fg(CYAN))));

    if let Some(last_update) = app.last_update {
        let elapsed = last_update.elapsed();
        lines.push(Line::from(""));
        lines.push(Line::from(vec![
            Span::styled("  Updated: ", Style::default().fg(MUTED)),
            Span::styled(format!("{}s ago", elapsed.as_secs()), Style::default().fg(ELECTRIC_BLUE)),
        ]));
    }

    let paragraph = Paragraph::new(lines)
        .style(Style::default().bg(DARK_BG));

    frame.render_widget(paragraph, area);
}

fn render_command_bar(frame: &mut Frame, app: &App, area: Rect) {
    let padding = " ".repeat(area.width as usize);

    let search_display = if app.mode == AppMode::Search {
        format!("search: {}█", app.search_query)
    } else {
        String::new()
    };

    let selected_info = if let Some(idx) = app.list_state.selected() {
        if let Some(entity) = app.filtered_entities.get(idx) {
            let name = entity.attributes.get("friendly_name")
                .and_then(|v| v.as_str())
                .unwrap_or(&entity.entity_id);
            format!("{} • {} / {}", name, idx + 1, app.filtered_entities.len())
        } else {
            String::new()
        }
    } else {
        String::new()
    };

    let line = Line::from(vec![
        Span::styled("└", Style::default().fg(MUTED)),
        Span::styled(" ◆ ", Style::default().fg(CYAN)),
        Span::styled(&search_display, Style::default().fg(CYAN)),
        if search_display.is_empty() {
            Span::styled(&selected_info, Style::default().fg(MUTED))
        } else {
            Span::raw("")
        },
        Span::styled(&padding, Style::default()),
    ]);

    frame.render_widget(Paragraph::new(line), area);
}

fn get_entity_visuals(entity: &EntityState, domain: &str) -> (&'static str, Color, Color) {
    let is_on = entity.state == "on" || entity.state == "playing" || entity.state == "home";
    let is_off = entity.state == "off" || entity.state == "idle" || entity.state == "away";

    match domain {
        "light" => {
            if is_on {
                ("◉", NEON_GREEN, HOT_PINK)
            } else {
                ("○", MUTED, Color::Gray)
            }
        }
        "switch" | "input_boolean" => {
            if is_on {
                ("⏻", NEON_GREEN, CYAN)
            } else {
                ("○", MUTED, Color::Gray)
            }
        }
        "climate" => {
            match entity.state.as_str() {
                "heat" => ("◈", ORANGE, ORANGE),
                "cool" => ("◈", ELECTRIC_BLUE, ELECTRIC_BLUE),
                _ => ("◈", CYAN, CYAN),
            }
        }
        "sensor" => {
            ("◎", ELECTRIC_BLUE, ELECTRIC_BLUE)
        }
        "binary_sensor" => {
            if is_on {
                ("●", HOT_PINK, HOT_PINK)
            } else {
                ("○", MUTED, Color::Gray)
            }
        }
        "media_player" => {
            match entity.state.as_str() {
                "playing" => ("▶", NEON_GREEN, MAGENTA),
                "paused" => ("⏸", ORANGE, MAGENTA),
                _ => ("⏹", MUTED, Color::Gray),
            }
        }
        "automation" => {
            if is_on {
                ("⚡", NEON_GREEN, MAGENTA)
            } else {
                ("○", MUTED, Color::Gray)
            }
        }
        "script" => {
            ("◆", MAGENTA, MAGENTA)
        }
        "person" | "device_tracker" => {
            if is_on {
                ("●", NEON_GREEN, CYAN)
            } else {
                ("○", MUTED, Color::Gray)
            }
        }
        _ => {
            if is_on {
                ("●", NEON_GREEN, NEON_GREEN)
            } else if is_off {
                ("○", MUTED, MUTED)
            } else {
                ("•", ELECTRIC_BLUE, ELECTRIC_BLUE)
            }
        }
    }
}

fn get_state_indicator(entity: &EntityState) -> &'static str {
    let is_on = entity.state == "on" || entity.state == "playing" || entity.state == "home";

    if is_on {
        "●"
    } else if entity.state == "off" || entity.state == "idle" || entity.state == "away" {
        "○"
    } else {
        "◐"
    }
}

fn truncate_str(s: &str, max_len: usize) -> String {
    if s.len() > max_len {
        format!("{}…", &s[..max_len.saturating_sub(1)])
    } else {
        s.to_string()
    }
}

fn render_entity_detail(frame: &mut Frame, app: &App) {
    if let Some(ref entity) = app.selected_entity {
        let area = centered_rect(70, 75, frame.area());

        let name = crate::ha_client::get_entity_name(entity);
        let domain = crate::ha_client::get_entity_domain(&entity.entity_id);
        let (icon, _, _) = get_entity_visuals(entity, domain);

        let entity_id_padding = " ".repeat(28 - entity.entity_id.len().min(28));
        let state_padding = " ".repeat(28 - entity.state.len().min(28));

        let mut lines = vec![
            Line::from(""),
            Line::from(vec![
                Span::styled("  ", Style::default()),
                Span::styled(icon, Style::default().fg(CYAN)),
                Span::styled(" ", Style::default()),
                Span::styled(&name, Style::default().fg(BRIGHT_WHITE).add_modifier(Modifier::BOLD)),
            ]),
            Line::from(""),
            Line::from(vec![
                Span::styled("  ┌─────────────────────────────┐", Style::default().fg(CYAN)),
            ]),
            Line::from(vec![
                Span::styled("  │ ", Style::default().fg(CYAN)),
                Span::styled("Entity ID: ", Style::default().fg(MUTED)),
                Span::styled(&entity.entity_id, Style::default().fg(ELECTRIC_BLUE)),
                Span::styled(&entity_id_padding, Style::default()),
                Span::styled("│", Style::default().fg(CYAN)),
            ]),
            Line::from(vec![
                Span::styled("  │ ", Style::default().fg(CYAN)),
                Span::styled("State:     ", Style::default().fg(MUTED)),
                Span::styled(&entity.state, Style::default().fg(NEON_GREEN)),
                Span::styled(&state_padding, Style::default()),
                Span::styled("│", Style::default().fg(CYAN)),
            ]),
            Line::from(vec![
                Span::styled("  └─────────────────────────────┘", Style::default().fg(CYAN)),
            ]),
            Line::from(""),
            Line::from(vec![
                Span::styled("  ▸ ATTRIBUTES", Style::default().fg(MAGENTA).add_modifier(Modifier::BOLD)),
            ]),
            Line::from(""),
        ];

        let mut attrs: Vec<_> = entity.attributes.iter().collect();
        attrs.sort_by_key(|(k, _)| *k);

        for (key, value) in attrs.iter().take(12) {
            let value_str = match value {
                serde_json::Value::String(s) => s.clone(),
                serde_json::Value::Number(n) => n.to_string(),
                serde_json::Value::Bool(b) => b.to_string(),
                _ => value.to_string(),
            };
            lines.push(Line::from(vec![
                Span::styled("    ", Style::default()),
                Span::styled(format!("{:16}", key), Style::default().fg(MUTED)),
                Span::styled(" │ ", Style::default().fg(GRID_COLOR)),
                Span::styled(truncate_str(&value_str, 30), Style::default().fg(BRIGHT_WHITE)),
            ]));
        }

        lines.push(Line::from(""));
        lines.push(Line::from(vec![
            Span::styled("  ", Style::default()),
            Span::styled("[Esc]", Style::default().fg(CYAN)),
            Span::styled(" Close", Style::default().fg(MUTED)),
        ]));

        let block = Block::default()
            .borders(Borders::ALL)
            .border_style(Style::default().fg(CYAN))
            .style(Style::default().bg(Color::Rgb(5, 5, 15)));

        frame.render_widget(Clear, area);
        frame.render_widget(Paragraph::new(lines).block(block), area);
    }
}

