pub struct HomeAssistantConfig {
    pub url: String,
    pub token: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            homeassistant: HomeAssistantConfig {
                url: "http://homeassistant.local:8123".to_string(),
                token: String::new(),
            },
        }
    }
}

impl Config {
    pub fn config_path() -> PathBuf {
        let config_dir = dirs::config_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("homeassistant-tui");
        std::fs::create_dir_all(&config_dir).ok();
        config_dir.join("config.toml")
    }

    pub fn load() -> anyhow::Result<Self> {
        let path = Self::config_path();
        if path.exists() {
            let content = std::fs::read_to_string(&path)?;
            let config: Config = toml::from_str(&content)?;
            Ok(config)
        } else {
            let config = Config::default();
            config.save()?;
            anyhow::bail!(
                "Created config file at {:?}. Please edit it with your Home Assistant URL and token.",
                path
            );
        }
    }

    pub fn save(&self) -> anyhow::Result<()> {
        let path = Self::config_path();
        let content = toml::to_string_pretty(self)?;
        std::fs::write(&path, content)?;
        Ok(())
    }

    #[allow(dead_code)]
    pub fn ws_url(&self) -> String {
        let url = self.homeassistant.url.trim_end_matches('/');
        url.replace("http://", "ws://")
            .replace("https://", "wss://")
            + "/api/websocket"
    }

    #[allow(dead_code)]
    pub fn api_url(&self) -> String {
        self.homeassistant.url.trim_end_matches('/').to_string()
    }
}

