pub struct HomeAssistantClient {
    client: Client,
    base_url: String,
    token: String,
}

impl HomeAssistantClient {
    pub fn new(url: String, token: String) -> Self {
        Self {
            client: Client::new(),
            base_url: url.trim_end_matches('/').to_string(),
            token,
        }
    }

    async fn request<T: DeserializeOwned>(&self, endpoint: &str) -> Result<T> {
        let url = format!("{}{}", self.base_url, endpoint);
        let response = self
            .client
            .get(&url)
            .header("Authorization", format!("Bearer {}", self.token))
            .header("Content-Type", "application/json")
            .send()
            .await?;

        if !response.status().is_success() {
            let status = response.status();
            let body = response.text().await.unwrap_or_default();
            return Err(anyhow!("API error {}: {}", status, body));
        }

        response.json::<T>().await.map_err(Into::into)
    }

    pub async fn get_states(&self) -> Result<Vec<EntityState>> {
        self.request("/api/states").await
    }

    #[allow(dead_code)]
    pub async fn get_entity(&self, entity_id: &str) -> Result<EntityState> {
        self.request(&format!("/api/states/{}", entity_id)).await
    }

    #[allow(dead_code)]
    pub async fn get_services(&self) -> Result<HashMap<String, Service>> {
        self.request("/api/services").await
    }

    pub async fn call_service(
        &self,
        domain: &str,
        service: &str,
        entity_id: Option<&str>,
        data: Option<HashMap<String, serde_json::Value>>,
    ) -> Result<Vec<EntityState>> {
        let url = format!("{}/api/services/{}/{}", self.base_url, domain, service);
        let mut body = data.unwrap_or_default();
        if let Some(id) = entity_id {
            body.insert("entity_id".to_string(), serde_json::json!(id));
        }

        let response = self
            .client
            .post(&url)
            .header("Authorization", format!("Bearer {}", self.token))
            .header("Content-Type", "application/json")
            .json(&body)
            .send()
            .await?;

        if !response.status().is_success() {
            let status = response.status();
            let body = response.text().await.unwrap_or_default();
            return Err(anyhow!("Service call error {}: {}", status, body));
        }

        response.json::<Vec<EntityState>>().await.map_err(Into::into)
    }

    pub async fn turn_on(&self, entity_id: &str) -> Result<Vec<EntityState>> {
        let domain = entity_id.split('.').next().unwrap_or("homeassistant");
        self.call_service(domain, "turn_on", Some(entity_id), None).await
    }

    pub async fn turn_off(&self, entity_id: &str) -> Result<Vec<EntityState>> {
        let domain = entity_id.split('.').next().unwrap_or("homeassistant");
        self.call_service(domain, "turn_off", Some(entity_id), None).await
    }

    pub async fn toggle(&self, entity_id: &str) -> Result<Vec<EntityState>> {
        let domain = entity_id.split('.').next().unwrap_or("homeassistant");
        self.call_service(domain, "toggle", Some(entity_id), None).await
    }

    #[allow(dead_code)]
    pub async fn set_light_brightness(&self, entity_id: &str, brightness: u8) -> Result<Vec<EntityState>> {
        let mut data = HashMap::new();
        data.insert("brightness".to_string(), serde_json::json!(brightness as u16));
        self.call_service("light", "turn_on", Some(entity_id), Some(data)).await
    }

    #[allow(dead_code)]
    pub async fn set_climate_temperature(&self, entity_id: &str, temperature: f32) -> Result<Vec<EntityState>> {
        let mut data = HashMap::new();
        data.insert("temperature".to_string(), serde_json::json!(temperature));
        self.call_service("climate", "set_temperature", Some(entity_id), Some(data)).await
    }

    #[allow(dead_code)]
    pub async fn test_connection(&self) -> Result<()> {
        let url = format!("{}/api/", self.base_url);
        let response = self
            .client
            .get(&url)
            .header("Authorization", format!("Bearer {}", self.token))
            .send()
            .await?;

        if response.status().is_success() {
            Ok(())
        } else {
            Err(anyhow!("Connection test failed: {}", response.status()))
        }
    }
}

pub fn get_entity_domain(entity_id: &str) -> &str {
    entity_id.split('.').next().unwrap_or("unknown")
}

pub fn get_entity_name(entity: &EntityState) -> String {
    entity
        .attributes
        .get("friendly_name")
        .and_then(|v| v.as_str())
        .unwrap_or(&entity.entity_id)
        .to_string()
}

pub fn format_entity_state(entity: &EntityState) -> String {
    let domain = get_entity_domain(&entity.entity_id);
    match domain {
        "light" => {
            if entity.state == "on" {
                let brightness = entity
                    .attributes
                    .get("brightness")
                    .and_then(|v| v.as_u64())
                    .map(|b| (b as f64 / 255.0 * 100.0) as u8)
                    .unwrap_or(100);
                format!("On ({}%)", brightness)
            } else {
                "Off".to_string()
            }
        }
        "climate" => {
            let temp = entity
                .attributes
                .get("current_temperature")
                .and_then(|v| v.as_f64());
            let target = entity
                .attributes
                .get("temperature")
                .and_then(|v| v.as_f64());
            let unit = entity
                .attributes
                .get("temperature_unit")
                .and_then(|v| v.as_str())
                .unwrap_or("°C");
            match (temp, target) {
                (Some(current), Some(t)) => {
                    format!("{} {} (target: {} {})", current, unit, t, unit)
                }
                (Some(current), None) => {
                    format!("{} {}", current, unit)
                }
                _ => entity.state.clone(),
            }
        }
        "sensor" => {
            let unit = entity
                .attributes
                .get("unit_of_measurement")
                .and_then(|v| v.as_str())
                .unwrap_or("");
            format!("{} {}", entity.state, unit).trim().to_string()
        }
        "binary_sensor" => {
            if entity.state == "on" {
                entity
                    .attributes
                    .get("device_class")
                    .and_then(|v| v.as_str())
                    .map(|dc| match dc {
                        "motion" => "Detected",
                        "door" | "window" => "Open",
                        "plug" => "Plugged",
                        _ => "Active",
                    })
                    .unwrap_or("On")
                    .to_string()
            } else {
                entity
                    .attributes
                    .get("device_class")
                    .and_then(|v| v.as_str())
                    .map(|dc| match dc {
                        "motion" => "Clear",
                        "door" | "window" => "Closed",
                        "plug" => "Unplugged",
                        _ => "Inactive",
                    })
                    .unwrap_or("Off")
                    .to_string()
            }
        }
        "switch" | "input_boolean" | "automation" | "script" => {
            if entity.state == "on" {
                "On".to_string()
            } else {
                "Off".to_string()
            }
        }
        "media_player" => {
            match entity.state.as_str() {
                "playing" => {
                    let media_title = entity
                        .attributes
                        .get("media_title")
                        .and_then(|v| v.as_str());
                    let media_artist = entity
                        .attributes
                        .get("media_artist")
                        .and_then(|v| v.as_str());
                    match (media_title, media_artist) {
                        (Some(title), Some(artist)) => format!("Playing: {} - {}", title, artist),
                        (Some(title), None) => format!("Playing: {}", title),
                        _ => "Playing".to_string(),
                    }
                }
                "paused" => "Paused".to_string(),
                "idle" => "Idle".to_string(),
                "off" => "Off".to_string(),
                _ => entity.state.clone(),
            }
        }
        _ => entity.state.clone(),
    }
}

use std::io;
use std::time::Duration;

use anyhow::Result;
use clap::Parser;
use crossterm::{
    event::{self, DisableMouseCapture, EnableMouseCapture, Event, KeyEventKind},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{backend::CrosstermBackend, Terminal};

mod config;
mod ha_client;
mod app;

use app::App;
use config::Config;

#[derive(Parser, Debug)]
#[command(name = "homeassistant-tui")]
#[command(about = "A TUI client for Home Assistant", long_about = None)]
struct Args {
    #[arg(short, long, help = "Run in demo mode with mock data")]
    demo: bool,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let mut app = if args.demo {
        App::new_demo()
    } else {
        let config = match Config::load() {
            Ok(c) => c,
            Err(e) => {
                disable_raw_mode()?;
                execute!(
                    terminal.backend_mut(),
                    LeaveAlternateScreen,
                    DisableMouseCapture
                )?;
                terminal.show_cursor()?;
                eprintln!("{}", e);
                return Ok(());
            }
        };
        App::new(config).await?
    };
    app.load_entities().await;

    let res = run_app(&mut terminal, &mut app).await;

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;

    if let Err(err) = res {
        eprintln!("Error: {:?}", err);
    }

    Ok(())
}

async fn run_app<B: ratatui::backend::Backend>(
    terminal: &mut Terminal<B>,
    app: &mut App,
) -> Result<()> {
    loop {
        terminal.draw(|f| app::render_app(f, app))?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                if key.kind == KeyEventKind::Press {
                    app.handle_key_event(key).await;
                }
            }
        }

        app.tick();

        if app.should_quit {
            return Ok(());
        }
    }
}
